import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"Account  – Payment Methods","description":"","frontmatter":{"title":"Account  – Payment Methods"},"headers":[],"relativePath":"operations-knowledge-base/presales-support/account-payment-methods.md","filePath":"operations-knowledge-base/presales-support/account-payment-methods.md","lastUpdated":1794292919000}'),i={name:"operations-knowledge-base/presales-support/account-payment-methods.md"};function o(d,e,s,c,l,h){return t(),r("div",null,[...e[0]||(e[0]=[n('<h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>To support convenient and secure payments, the platform provides a credit card payment method management feature.</p><p>Through this feature, users can add and manage credit card information to help ensure smooth payment for various transactions. The following sections explain the related operations and important notes for managing credit card payment methods.</p><h2 id="_2-access-path" tabindex="-1">2. Access Path <a class="header-anchor" href="#_2-access-path" aria-label="Permalink to &quot;2. Access Path&quot;">​</a></h2><p>Users can navigate to Top-right profile icon → Account → Payment Methods → Add New Credit Card to enter the credit card payment management page and manage credit card information.</p><h2 id="_3-operation-guide" tabindex="-1">3. Operation Guide <a class="header-anchor" href="#_3-operation-guide" aria-label="Permalink to &quot;3. Operation Guide&quot;">​</a></h2><h3 id="_1-add-a-new-payment-method" tabindex="-1">(1) Add a New Payment Method <a class="header-anchor" href="#_1-add-a-new-payment-method" aria-label="Permalink to &quot;(1) Add a New Payment Method&quot;">​</a></h3><h4 id="select-type" tabindex="-1">Select Type <a class="header-anchor" href="#select-type" aria-label="Permalink to &quot;Select Type&quot;">​</a></h4><p>Choose “Credit Card” as the payment type.</p><h4 id="description-optional" tabindex="-1">Description (Optional) <a class="header-anchor" href="#description-optional" aria-label="Permalink to &quot;Description (Optional)&quot;">​</a></h4><p>You may add a note or description for the credit card to help identify and manage it later.</p><h4 id="enter-credit-card-number" tabindex="-1">Enter Credit Card Number <a class="header-anchor" href="#enter-credit-card-number" aria-label="Permalink to &quot;Enter Credit Card Number&quot;">​</a></h4><p>Enter the credit card number accurately.</p><p>If the system displays the message “The card number you entered appears to be invalid. Please try again.”, please carefully verify the card number and enter it again.</p><h4 id="set-expiration-date" tabindex="-1">Set Expiration Date <a class="header-anchor" href="#set-expiration-date" aria-label="Permalink to &quot;Set Expiration Date&quot;">​</a></h4><p>Enter the credit card expiration date in the Month / Year format.</p><h4 id="enter-cvv-cvc2" tabindex="-1">Enter CVV/CVC2 <a class="header-anchor" href="#enter-cvv-cvc2" aria-label="Permalink to &quot;Enter CVV/CVC2&quot;">​</a></h4><p>Enter the CVV/CVC2 security code in the designated field.</p><p>If you are unsure where to find this code, click “Where can I find this number?” for guidance.</p><h4 id="select-billing-address" tabindex="-1">Select Billing Address <a class="header-anchor" href="#select-billing-address" aria-label="Permalink to &quot;Select Billing Address&quot;">​</a></h4><p>You can select an existing billing address or click “Add New Address” to enter a new billing address.</p><h4 id="save-changes" tabindex="-1">Save Changes <a class="header-anchor" href="#save-changes" aria-label="Permalink to &quot;Save Changes&quot;">​</a></h4><p>After confirming that all information is correct, click “Save Changes” to add the new payment method.</p><p>If you do not want to continue, click “Cancel.”</p><h3 id="_2-edit-and-manage-payment-information" tabindex="-1">(2) Edit and Manage Payment Information <a class="header-anchor" href="#_2-edit-and-manage-payment-information" aria-label="Permalink to &quot;(2) Edit and Manage Payment Information&quot;">​</a></h3><p>If you need to modify existing credit card information, locate the corresponding card on the Payment Methods management page and edit the details as needed.</p><h4 id="set-as-default" tabindex="-1">Set as Default <a class="header-anchor" href="#set-as-default" aria-label="Permalink to &quot;Set as Default&quot;">​</a></h4><p>If multiple credit cards are available, you can set one as the default payment method. Future transactions will use this card first by default.</p><h4 id="edit" tabindex="-1">Edit <a class="header-anchor" href="#edit" aria-label="Permalink to &quot;Edit&quot;">​</a></h4><p>Click the “Edit” button to update information such as the expiration date or billing address, ensuring that your payment details remain accurate and valid.</p><h4 id="delete" tabindex="-1">Delete <a class="header-anchor" href="#delete" aria-label="Permalink to &quot;Delete&quot;">​</a></h4><p>If a credit card is no longer used for payments, click “Delete” to remove it from your account.</p><h2 id="_4-important-notes" tabindex="-1">4. Important Notes <a class="header-anchor" href="#_4-important-notes" aria-label="Permalink to &quot;4. Important Notes&quot;">​</a></h2><h4 id="information-accuracy" tabindex="-1">Information Accuracy <a class="header-anchor" href="#information-accuracy" aria-label="Permalink to &quot;Information Accuracy&quot;">​</a></h4><p>Please ensure that key credit card details, including the card number, expiration date, and CVV/CVC2, are entered correctly to avoid payment failures or account risks.</p><h4 id="security-protection" tabindex="-1">Security Protection <a class="header-anchor" href="#security-protection" aria-label="Permalink to &quot;Security Protection&quot;">​</a></h4><p>Please keep your credit card information secure and do not share it with others. The platform uses security measures to protect user information, but users should also remain vigilant to prevent misuse.</p><h4 id="monitor-expiration-dates" tabindex="-1">Monitor Expiration Dates <a class="header-anchor" href="#monitor-expiration-dates" aria-label="Permalink to &quot;Monitor Expiration Dates&quot;">​</a></h4><p>Please check your credit card expiration date regularly and update the payment method before the card expires to avoid payment interruptions.</p><h4 id="handling-system-alerts" tabindex="-1">Handling System Alerts <a class="header-anchor" href="#handling-system-alerts" aria-label="Permalink to &quot;Handling System Alerts&quot;">​</a></h4><p>If the system displays an alert message (e.g., an invalid card number), please verify the information carefully and follow the instructions. If the issue persists, please contact customer service for assistance.</p><p>Through the credit card payment method feature, the platform provides users with a flexible and secure payment management option, helping them complete transactions more efficiently and improving the overall user experience.</p>',42)])])}const u=a(i,[["render",o]]);export{m as __pageData,u as default};
